// Seeded RNG: determinism by construction (plain JS)
function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0; a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
// Planners draw from THEIR seeded RNG (injected, logged), never Math.random.
// Same seed + inputs → identical choices → identical traces, provably.

// Dry-run harness: stub effects, run full logic, diff behaviors (plain JS)
function dryRun(loop, stubs) {
  const calls = [];
  const stubbed = new Proxy({}, { get: (_, tool) => async (...args) => {
    calls.push([tool, args]);
    if (!(tool in stubs)) throw new Error("unstubbed-tool:" + tool);
    return stubs[tool];
  }});
  return loop(stubbed).then((result) => ({ result, calls }));
}
// Unstubbed-tool errors prove coverage gaps: every effect the logic touches must stub.

